<?php declare( strict_types=1 ); namespace Amanah\SEOEngine\AI; defined( 'ABSPATH' ) || exit; final class AIStructuredValidator { public function validate(string $content,array $required_keys=array()): array{$data=json_decode($content,true);if(!is_array($data))return array('valid'=>false,'errors'=>array('invalid_json'));$errors=array();foreach($required_keys as $key)if(!array_key_exists($key,$data))$errors[]='missing_'.$key;return array('valid'=>empty($errors),'errors'=>$errors,'data'=>$data);} }